// ShopServiceServer is the server API for ShopService service.
// All implementations must embed UnimplementedShopServiceServer
// for forward compatibility.
//
// ShopService 是 shop 业务服务的 gRPC 边界。
// 默认 CRUD 契约可直接调用；支付相关 RPC 复用 bw-cli-main pkg/gopay 逻辑，
// 按 shop 自身字段设计（金额统一 int64 分）。
type ShopServiceServer interface {
	CreateShop(context.Context, *CreateShopRequest) (*ShopResponse, error)
	GetShop(context.Context, *GetShopRequest) (*ShopResponse, error)
	ListShops(context.Context, *ListShopsRequest) (*ListShopsResponse, error)
	UpdateShop(context.Context, *UpdateShopRequest) (*ShopResponse, error)
	DeleteShop(context.Context, *DeleteShopRequest) (*DeleteShopResponse, error)
	// Pay 发起 WAP/PC 网页支付，scene 取 wap / page。
	Pay(context.Context, *PayRequest) (*PayResponse, error)
	// ScanPay 发起扫码支付（当面付），返回二维码链接。
	ScanPay(context.Context, *ScanPayRequest) (*ScanPayResponse, error)
	// BarCodePay 发起付款码支付（商家扫用户付款码），同步扣款。
	BarCodePay(context.Context, *BarCodePayRequest) (*BarCodePayResponse, error)
	// Refund 发起退款。
	Refund(context.Context, *RefundRequest) (*RefundResponse, error)
	// NotifyPayment 处理支付渠道异步通知回调（支付宝表单 / 微信 JSON）。
	NotifyPayment(context.Context, *NotifyPaymentRequest) (*NotifyPaymentResponse, error)
	// QueryPayment 按 order_no 查询本地支付单，并可选调渠道查单接口刷新状态。
	QueryPayment(context.Context, *QueryPaymentRequest) (*QueryPaymentResponse, error)
	// P08：AppendTrajectory 上报单个行程轨迹点（append-only，含质量校验）。
	AppendTrajectory(context.Context, *AppendTrajectoryRequest) (*TrajectoryResponse, error)
	// P08：ListTrajectories 按订单查询轨迹点（上报时间升序）。
	ListTrajectories(context.Context, *ListTrajectoriesRequest) (*ListTrajectoriesResponse, error)
	// P09：BindVirtualNumber 绑定订单虚拟号（仅可联系状态允许）。
	BindVirtualNumber(context.Context, *BindVirtualNumberRequest) (*VirtualNumberResponse, error)
	// P09：GetVirtualNumber 按订单查询虚拟号。
	GetVirtualNumber(context.Context, *GetVirtualNumberRequest) (*VirtualNumberResponse, error)
	// P09：ReleaseVirtualNumber 行程结束/取消时释放虚拟号。
	ReleaseVirtualNumber(context.Context, *ReleaseVirtualNumberRequest) (*VirtualNumberResponse, error)
	// P10：RequestDestinationChange 乘客发起中途改点（最多 2 次）。
	RequestDestinationChange(context.Context, *RequestDestinationChangeRequest) (*DestinationChangeResponse, error)
	// P10：ConfirmDestinationChange 司机确认改点。
	ConfirmDestinationChange(context.Context, *ConfirmDestinationChangeRequest) (*DestinationChangeResponse, error)
	// P10：RejectDestinationChange 司机拒绝改点。
	RejectDestinationChange(context.Context, *RejectDestinationChangeRequest) (*DestinationChangeResponse, error)
	// P10：CancelDestinationChange 乘客撤销改点申请。
	CancelDestinationChange(context.Context, *CancelDestinationChangeRequest) (*DestinationChangeResponse, error)
	// P10：ListDestinationChanges 按订单查询全部改点申请。
	ListDestinationChanges(context.Context, *ListDestinationChangesRequest) (*ListDestinationChangesResponse, error)
	// P11：CreateTripShare 创建行程分享（生成不可推导令牌）。
	CreateTripShare(context.Context, *CreateTripShareRequest) (*TripShareResponse, error)
	// P11：AccessTripShare 通过令牌访问行程分享。
	AccessTripShare(context.Context, *AccessTripShareRequest) (*TripShareResponse, error)
	// P11：RevokeTripShare 撤销行程分享。
	RevokeTripShare(context.Context, *RevokeTripShareRequest) (*TripShareResponse, error)
	// P12：QuoteCancelFee 生成取消报价（免费窗口判定 + 绑定订单版本）。
	QuoteCancelFee(context.Context, *QuoteCancelFeeRequest) (*CancelQuoteResponse, error)
	// P12：GetLatestCancelQuote 查询订单最新取消报价。
	GetLatestCancelQuote(context.Context, *GetLatestCancelQuoteRequest) (*CancelQuoteResponse, error)
	// P12：ConsumeCancelQuote 消费取消报价（校验未使用/未过期/版本一致）。
	ConsumeCancelQuote(context.Context, *ConsumeCancelQuoteRequest) (*CancelQuoteResponse, error)
	// P14：IssueUserCoupon 发券（券码唯一，初始 AVAILABLE）。
	IssueUserCoupon(context.Context, *IssueUserCouponRequest) (*UserCouponResponse, error)
	// P14：GetUserCoupon 按券码查询单张券。
	GetUserCoupon(context.Context, *GetUserCouponRequest) (*UserCouponResponse, error)
	// P14：ListUserCoupons 按用户查询券列表（可按状态过滤）。
	ListUserCoupons(context.Context, *ListUserCouponsRequest) (*ListUserCouponsResponse, error)
	// P14：CountUsableCoupons 统计用户可用券数（下单页角标）。
	CountUsableCoupons(context.Context, *CountUsableCouponsRequest) (*CountUsableCouponsResponse, error)
	// P14：LockUserCoupon 下单锁券 AVAILABLE → LOCKED。
	LockUserCoupon(context.Context, *LockUserCouponRequest) (*UserCouponResponse, error)
	// P14：UseUserCoupon 支付成功核销 LOCKED → USED。
	UseUserCoupon(context.Context, *UseUserCouponRequest) (*UserCouponResponse, error)
	// P14：ReleaseUserCoupon 支付失败/取消订单解锁 LOCKED → AVAILABLE。
	ReleaseUserCoupon(context.Context, *ReleaseUserCouponRequest) (*UserCouponResponse, error)
	// P14：ExpireUserCoupons 过期扫描，批量把超期未用券标记 EXPIRED。
	ExpireUserCoupons(context.Context, *ExpireUserCouponsRequest) (*ExpireUserCouponsResponse, error)
	// P14：VoidUserCoupon 作废券（风控/运营介入 AVAILABLE/LOCKED → VOID）。
	VoidUserCoupon(context.Context, *VoidUserCouponRequest) (*UserCouponResponse, error)
	mustEmbedUnimplementedShopServiceServer()
}

